const familyKey=m=>m.id.split('/').slice(0,2).join('/');
function familyName(m){return m.id.split('/')[1].replace(/^seedream-v/,'Seedream ').replace(/^seedance-/,'Seedance ').replace(/^gpt-image-/,'GPT Image ').replace(/^nano-banana/,'Nano Banana').replace(/^gemini-omni/,'Gemini Omni').replace(/^kling-v/,'Kling ').replace(/^flux-/,'FLUX ').replace(/^qwen-/,'Qwen ').replace(/-/g,' ').replace(/\b[a-z]/g,c=>c.toUpperCase()).replace('Gpt','GPT');}
function modeName(m){const path=m.id.split('/').slice(2).join(' / ');return modeNames[path]||(path?path.replaceAll('-',' ').replace(/\b[a-z]/g,c=>c.toUpperCase()):modeNames[m.type]||m.type.replaceAll('-',' '));}
function label(m){return familyName(m);}
